package ca.stewark.helioflux.core.data.repository

import ca.stewark.helioflux.core.data.network.*
import ca.stewark.helioflux.core.database.dao.*
import ca.stewark.helioflux.core.database.entity.*
import ca.stewark.helioflux.core.model.*
import java.time.Instant
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.test.runTest
import org.junit.Assert.*
import org.junit.Test

class SolarImageryRepositoryTest {
 private val hmibcUrl="https://iswa.ccmc.gsfc.nasa.gov/iswa_data_tree/observation/solar/sdo/hmi-magnetogram-color_2048x2048/2026/09/20260922_111500_2048_HMIBC.jpg"
 private val hmibcJson="""{"iswa_sdo_aia_hmic_files":{"samples":[{"timestamp":"2026-09-22 11:15:00.0","url":"$hmibcUrl"}]}}"""
 @Test fun sourcesPersistIndependentlyWhenOneFails()=runTest{val f=Fakes();val r=f.repo();f.http.getStatus[HelioFluxEndpoints.hmiMetadata]=500;f.http.getBody[HelioFluxEndpoints.hek]="""{"result":[{"ar_noaanum":"11234","hpc_x":10,"hpc_y":20}]}""";f.http.getBody[HelioFluxEndpoints.enlil]="""<a href="enlil_com2_1_20260919T120000.jpg">x</a>""";r.refreshAll();assertTrue(r.image(SolarImageType.Magnetogram).first() is RepositoryState.Failure);assertEquals(1,(r.regions().first() as RepositoryState.Available).data.size);assertEquals(1,(r.enlil().first() as RepositoryState.Available).data.size)}
 @Test fun refreshAllUsesWorkingLascoAnimationEndpoints()=runTest{val f=Fakes();val r=f.repo();f.http.getBody[HelioFluxEndpoints.hmiMetadata]=hmibcJson;r.refreshAll();assertNotNull(f.image.m[SolarImageType.LascoC2]?.value);assertEquals(HelioFluxEndpoints.lasco+"LATEST/current_c2.gif",f.image.m[SolarImageType.LascoC2]?.value?.url);assertEquals(HelioFluxEndpoints.lasco+"LATEST/current_c3.gif",f.image.m[SolarImageType.LascoC3]?.value?.url)}
 @Test fun headLastModifiedBecomesNormalizedTimestamp()=runTest{val f=Fakes();val r=f.repo();val url=HelioFluxEndpoints.lasco+"LATEST/current_c2.gif";f.http.headers[url]=mapOf("Last-Modified" to listOf("Sat, 19 Sep 2026 12:00:00 GMT"));r.refreshImage(SolarImageType.LascoC2,url);assertEquals(1789819200000L,(r.image(SolarImageType.LascoC2).first() as RepositoryState.Available).data.sourceTimestampMillis)}
 @Test fun magnetogramRefreshUsesRecentLaTiSWindow()=runTest{val f=Fakes();val r=f.repo();val end=Instant.parse("2026-09-22T11:20:00Z").toEpochMilli();val start=end-24*60*60*1000L;val expected="https://lasp.colorado.edu/space-weather-portal/latis/dap/iswa_sdo_aia_hmic_files.json?time%3E="+Instant.ofEpochMilli(start)+"&time%3C="+Instant.ofEpochMilli(end)+"&takeRight(1)&project(time,url)";f.http.getBody[expected]=hmibcJson;r.refreshMagnetogram();assertEquals(listOf(expected),f.http.requestedGets);assertTrue(r.image(SolarImageType.Magnetogram).first() is RepositoryState.Available)}\n @Test fun magnetogramRefreshPersistsLatestLaTiSHmibcSample()=runTest{val f=Fakes();val r=f.repo();f.http.getBody[HelioFluxEndpoints.hmiMetadata]=hmibcJson;r.refreshMagnetogram();val image=(r.image(SolarImageType.Magnetogram).first() as RepositoryState.Available).data;val timestamp=Instant.parse("2026-09-22T11:15:00Z").toEpochMilli();assertEquals(timestamp,image.sourceTimestampMillis);assertEquals(hmibcUrl,image.url);assertEquals(timestamp,f.status.get(SolarImageryRepository.HMI)?.observationTimestampMillis)}
 @Test fun failedMagnetogramRefreshRetainsPreviousHmibcAsCached()=runTest{val f=Fakes();val r=f.repo();f.http.getBody[HelioFluxEndpoints.hmiMetadata]=hmibcJson;r.refreshMagnetogram();val previous=f.image.m[SolarImageType.Magnetogram]?.value;f.http.getStatus[HelioFluxEndpoints.hmiMetadata]=500;r.refreshMagnetogram();val state=r.image(SolarImageType.Magnetogram).first() as RepositoryState.Failure;assertEquals(previous?.url,state.retainedData?.url);assertEquals(previous?.sourceTimestampMillis,state.retainedData?.sourceTimestampMillis);assertEquals(DataFreshness.Cached,state.freshness);assertEquals(previous,f.image.m[SolarImageType.Magnetogram]?.value);assertFalse(f.http.requestedGets.any{it.contains("/api/hmi/")})}
 private class Fakes{val image=Images();val region=Regions();val enlil=Enlil();val status=Status();val http=Http();fun repo()=SolarImageryRepository(image,region,enlil,status,http){Instant.parse("2026-09-22T11:20:00Z").toEpochMilli()}}
 private class Http:HttpTransport{val headStatus=mutableMapOf<String,Int>();val getStatus=mutableMapOf<String,Int>();val getBody=mutableMapOf<String,String>();val headers=mutableMapOf<String,Map<String,List<String>>>();val requestedGets=mutableListOf<String>();override suspend fun head(url:String)=HttpResult(headStatus[url]?:200,"",headers[url]?:emptyMap());override suspend fun get(url:String):HttpResult{requestedGets+=url;return HttpResult(getStatus[url]?:200,getBody[url]?:"",emptyMap())}}
 private class Images:SolarImageDao{val m=mutableMapOf<SolarImageType,MutableStateFlow<SolarImageEntity?>>();override suspend fun upsert(image:SolarImageEntity){m.getOrPut(image.type){MutableStateFlow(null)}.value=image};override suspend fun getLatest(type:SolarImageType)=m[type]?.value;override fun observeLatest(type:SolarImageType):Flow<SolarImageEntity?> = m.getOrPut(type){MutableStateFlow(null)}}
 private class Regions:ActiveRegionDao(){val flow=MutableStateFlow<List<ActiveRegionEntity>>(emptyList());override suspend fun getAll()=flow.value;override fun observeAll():Flow<List<ActiveRegionEntity>> = flow;override suspend fun deleteAll(){flow.value=emptyList()};override suspend fun upsertAll(regions:List<ActiveRegionEntity>){flow.value=regions}}
 private class Enlil:EnlilFrameDao{val flow=MutableStateFlow<List<EnlilFrameEntity>>(emptyList());override suspend fun upsertAll(frames:List<EnlilFrameEntity>){flow.value=frames};override suspend fun getOrdered()=flow.value;override fun observeOrdered():Flow<List<EnlilFrameEntity>> = flow;override suspend fun deleteOtherRuns(runTimestampMillis:Long){flow.value=flow.value.filter{it.runTimestampMillis==runTimestampMillis}}}
 private class Status:DataSourceStatusDao{val m=mutableMapOf<DataSourceKey,MutableStateFlow<DataSourceStatusEntity?>>();override suspend fun upsert(status:DataSourceStatusEntity){m.getOrPut(status.source){MutableStateFlow(null)}.value=status};override suspend fun get(source:DataSourceKey)=m[source]?.value;override fun observe(source:DataSourceKey):Flow<DataSourceStatusEntity?> = m.getOrPut(source){MutableStateFlow(null)}}
}
